use clap::{App as ClapApp, AppSettings, Arg, ArgGroup, SubCommand};

use crate::config::ParserSettings;

pub struct AppBuilder {
    about: &'static str,
    long_about: &'static str,
}

impl AppBuilder {
    pub fn new() -> Self {
        AppBuilder {
            about: "A cat(1) clone with wings.\n\n\
             Use '--help' instead of '-h' to see a more detailed version of the help text.",
            long_about: "A cat(1) clone with syntax highlighting and Git integration.",
        }
    }

    pub fn build(&self, settings: &ParserSettings) -> ClapApp<'static, 'static> {
        let clap_color_setting = if settings.colored_help() {
            AppSettings::ColoredHelp
        } else {
            AppSettings::ColorNever
        };

        let mut clap_app = ClapApp::new(crate_name!())
            .version(crate_version!())
            .global_setting(clap_color_setting)
            .global_setting(AppSettings::DeriveDisplayOrder)
            .global_setting(AppSettings::UnifiedHelpMessage)
            .global_setting(AppSettings::HidePossibleValuesInHelp);

        if settings.infer_subcommands() {
            clap_app = clap_app.setting(AppSettings::InferSubcommands);
        }

        if settings.args_negate_subcommands() {
            clap_app = clap_app.setting(AppSettings::ArgsNegateSubcommands);
        }

        if settings.disable_help_subcommand() {
            clap_app = clap_app.setting(AppSettings::DisableHelpSubcommand);
        }

        if settings.versionless_subcommands() {
            clap_app = clap_app.setting(AppSettings::VersionlessSubcommands);
        }

        clap_app
        .max_term_width(settings.max_term_width())
        .about(self.about)
        .long_about(self.long_about)
